// Core tests: the 18 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and invariant cases from the
// SPEC's tests section. The extra expected values were derived with an
// independent Python datetime calculation and by hand from the SPEC's
// rules before the product code existed.

import assert from "node:assert/strict";
import test from "node:test";
import { dateToJdn, jdnToDate, run } from "../public/js/core/period.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { lastPeriodStart: "2026-10-26", cycleLength: "28", periodLength: "5" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("the earliest legal date 1900-01-01 is accepted, hand-derived rows", () => {
  const outcome = run({ lastPeriodStart: "1900-01-01", cycleLength: "21", periodLength: "1" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(
    outcome.result.cycles.map((c) => [c.start, c.periodEnd, c.ovulation]),
    [
      ["1900-01-01", "1900-01-01", "1900-01-08"],
      ["1900-01-22", "1900-01-22", "1900-01-29"],
      ["1900-02-12", "1900-02-12", "1900-02-19"],
      ["1900-03-05", "1900-03-05", "1900-03-12"],
    ],
  );
});

test("the latest legal date 2100-12-31 is accepted and predictions extend into 2101", () => {
  const outcome = run({ lastPeriodStart: "2100-12-31", cycleLength: "28", periodLength: "5" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(
    outcome.result.cycles.map((c) => [c.start, c.periodEnd, c.ovulation]),
    [
      ["2100-12-31", "2101-01-04", "2101-01-14"],
      ["2101-01-28", "2101-02-01", "2101-02-11"],
      ["2101-02-25", "2101-03-01", "2101-03-11"],
      ["2101-03-25", "2101-03-29", "2101-04-08"],
    ],
  );
});

test("2101-01-01 input is RANGE (one day past the input range)", () => {
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2101-01-01" }), {
    code: "RANGE",
    field: "lastPeriodStart",
    row: null,
  });
});

test("maximum cycle and period lengths together (35 / 10)", () => {
  const outcome = run({ lastPeriodStart: "2026-10-26", cycleLength: "35", periodLength: "10" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(
    outcome.result.cycles.map((c) => [c.start, c.periodEnd, c.ovulation]),
    [
      ["2026-10-26", "2026-11-04", "2026-11-16"],
      ["2026-11-30", "2026-12-09", "2026-12-21"],
      ["2027-01-04", "2027-01-13", "2027-01-25"],
      ["2027-02-08", "2027-02-17", "2027-03-01"],
    ],
  );
});

test("leap-day rules: 2000-02-29 and 2028-02-29 exist; 1900-02-29 and 2026-02-29 do not", () => {
  assert.equal(run({ ...base, lastPeriodStart: "2000-02-29" }).ok, true);
  assert.equal(run({ ...base, lastPeriodStart: "2028-02-29" }).ok, true);
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "1900-02-29" }), {
    code: "INVALID_DATE",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2026-02-29" }), {
    code: "INVALID_DATE",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2026-13-01" }), {
    code: "INVALID_DATE",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2026-04-31" }), {
    code: "INVALID_DATE",
    field: "lastPeriodStart",
    row: null,
  });
});

test("grammar: unpadded dates, whitespace, signs, and full-width digits are format errors", () => {
  // Note: a date padded with a space is 11 UTF-16 units, so the capacity
  // check (INPUT_LIMIT, asserted in the capacity test) fires before the
  // grammar check; only 10-unit-or-shorter malformed dates reach it.
  for (const bad of ["2026-1-26", "2026-10-6", "20261026"]) {
    assert.deepEqual(errorOf({ ...base, lastPeriodStart: bad }), {
      code: "DATE_FORMAT",
      field: "lastPeriodStart",
      row: null,
    });
  }
  for (const bad of ["+28", "-28", "28 ", " 28", "２８", "2.8e1"]) {
    assert.deepEqual(errorOf({ ...base, cycleLength: bad }), {
      code: "INTEGER_FORMAT",
      field: "cycleLength",
      row: null,
    });
  }
});

test("capacity is checked before grammar: an 11-unit date and a 9-unit count are INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2026-10-266" }), {
    code: "INPUT_LIMIT",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: " 2026-10-26" }), {
    code: "INPUT_LIMIT",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, cycleLength: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "cycleLength",
    row: null,
  });
  // An 8-unit count reaches the grammar check, not the range check.
  assert.deepEqual(errorOf({ ...base, cycleLength: "99999999" }), {
    code: "RANGE",
    field: "cycleLength",
    row: null,
  });
});

test("lone surrogates are UNICODE, checked before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...base, cycleLength: "\uD800" }), {
    code: "UNICODE",
    field: "cycleLength",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lastPeriodStart: "2026-10-2\uDC00" }), {
    code: "UNICODE",
    field: "lastPeriodStart",
    row: null,
  });
  // A well-formed surrogate pair is not UNICODE; it fails the grammar.
  assert.deepEqual(errorOf({ ...base, cycleLength: "\uD83D\uDE00" }), {
    code: "INTEGER_FORMAT",
    field: "cycleLength",
    row: null,
  });
});

test("empty counts are EMPTY, not grammar errors", () => {
  assert.deepEqual(errorOf({ ...base, cycleLength: "" }), {
    code: "EMPTY",
    field: "cycleLength",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, periodLength: "" }), {
    code: "EMPTY",
    field: "periodLength",
    row: null,
  });
});

test("field order: the first field's error wins over later fields", () => {
  assert.deepEqual(errorOf({ lastPeriodStart: "2026/10/26", cycleLength: "36", periodLength: "0" }), {
    code: "DATE_FORMAT",
    field: "lastPeriodStart",
    row: null,
  });
  assert.deepEqual(errorOf({ lastPeriodStart: "2026-10-26", cycleLength: "36", periodLength: "0" }), {
    code: "RANGE",
    field: "cycleLength",
    row: null,
  });
});

test("schema: missing fields, wrong types, null, arrays, and accessors are SCHEMA", () => {
  assert.deepEqual(errorOf({ cycleLength: "28", periodLength: "5" }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, cycleLength: 28 }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf(null), { code: "SCHEMA", field: null, row: null });
  assert.deepEqual(errorOf(["2026-10-26", "28", "5"]), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  const withAccessor = { lastPeriodStart: "2026-10-26", periodLength: "5" };
  Object.defineProperty(withAccessor, "cycleLength", {
    enumerable: true,
    get() {
      throw new Error("accessor must never be read");
    },
  });
  assert.deepEqual(errorOf(withAccessor), { code: "SCHEMA", field: null, row: null });
});

test("invariants hold for every legal combination sampled", () => {
  const inputs = [
    { lastPeriodStart: "2024-02-28", cycleLength: "21", periodLength: "1" },
    { lastPeriodStart: "2026-12-31", cycleLength: "35", periodLength: "10" },
    { lastPeriodStart: "2000-02-29", cycleLength: "29", periodLength: "6" },
    { lastPeriodStart: "2099-06-15", cycleLength: "24", periodLength: "3" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    const cycle = Number(input.cycleLength);
    const period = Number(input.periodLength);
    const jdns = outcome.result.cycles.map((row) => ({
      start: dateToJdn(...row.start.split("-").map(Number)),
      periodEnd: dateToJdn(...row.periodEnd.split("-").map(Number)),
      ovulation: dateToJdn(...row.ovulation.split("-").map(Number)),
      fertileStart: dateToJdn(...row.fertileStart.split("-").map(Number)),
      fertileEnd: dateToJdn(...row.fertileEnd.split("-").map(Number)),
    }));
    for (let i = 0; i < 4; i += 1) {
      assert.equal(outcome.result.cycles[i].index, i);
      if (i > 0) assert.equal(jdns[i].start - jdns[i - 1].start, cycle);
      assert.equal(jdns[i].periodEnd - jdns[i].start, period - 1);
      assert.equal(jdns[i].ovulation - jdns[i].start, cycle - 14);
      assert.equal(jdns[i].fertileEnd - jdns[i].fertileStart, 6);
      assert.equal(jdns[i].ovulation - jdns[i].fertileStart, 5);
    }
  }
});

test("JDN round-trip is exact across the whole input range (stepped sweep)", () => {
  const min = dateToJdn(1900, 1, 1);
  const max = dateToJdn(2101, 12, 31);
  assert.equal(min, 2415021);
  assert.equal(dateToJdn(2000, 1, 1), 2451545);
  for (let jdn = min; jdn <= max; jdn += 97) {
    const { year, month, day } = jdnToDate(jdn);
    assert.equal(dateToJdn(year, month, day), jdn);
  }
});

test("results are identical under different process time zones", () => {
  // The core never reads the clock or zone; this pins the property at the
  // value level by re-running the leap fixture after TZ mutations that a
  // host-clock implementation would leak.
  const fixture = fixtures.cases.find((entry) => entry.id === "leap-february");
  const before = run(fixture.input);
  process.env.TZ = "Pacific/Kiritimati";
  const after = run(fixture.input);
  process.env.TZ = "America/New_York";
  const third = run(fixture.input);
  assert.deepEqual(after, before);
  assert.deepEqual(third, fixture.expected);
});
